export default function App(){
 const [token,setToken]=useState('');
 const [user,setUser]=useState<Principal|null>(()=>DEMO?fixtureUser:null);
 const [route,setRoute]=useState(()=>window.location.hash.slice(1)||'dashboard'),[loading,setLoading]=useState(!DEMO);
 const [authError,setAuthError]=useState('');
 useEffect(()=>{const h=()=>setRoute(window.location.hash.slice(1)||'dashboard');window.addEventListener('hashchange',h);return()=>window.removeEventListener('hashchange',h)},[]);
 useEffect(()=>{if(DEMO)return;refreshSession().then(x=>{setToken(x.accessToken);setUser(x.user)}).catch(()=>{setAccessToken('');setToken('');setUser(null)}).finally(()=>setLoading(false))},[]);
 const navigate:Navigator=(page,id)=>{window.location.hash=page+(id?'/'+id:'');setRoute(page+(id?'/'+id:''));window.scrollTo({top:0,behavior:'instant'})};
 const login=(t:string,u:Principal)=>{setAccessToken(t);setToken(t);setUser(u);navigate('dashboard')};
 const forget=()=>{setAccessToken('');setToken('');setUser(null);window.location.hash='';};
 useEffect(()=>{const onExpired=()=>forget();window.addEventListener('assettrust:session-expired',onExpired);return()=>window.removeEventListener('assettrust:session-expired',onExpired)},[]);
 const logout=()=>{if(!DEMO)post('/auth/logout',token,{}).catch(()=>{}).finally(forget);else forget()};
 if(route==='receive/report')return <ReportRecipientPage/>;
 if(route==='reset-password'||route.startsWith('reset-password/'))return <PasswordRecoveryPage key={route} initialToken={route.startsWith('reset-password/')?route.slice('reset-password/'.length):''}/>;
 if(route.startsWith('verify/report/'))return <PublicReportVerificationPage reportId={route.slice('verify/report/'.length)}/>;
 if(loading)return <div className="loading-page"><Brand/><p>Checking your secure workspace...</p></div>;
 if(!user)return <><Auth onAuth={login}/>{authError&&<ErrorBox message={authError}/>}</>;
 if(user.adminMfaRequired && !user.adminMfaEnrolled){
  return <RequiredAdminMfa token={token} onLogout={forget} onReady={()=>{api<Principal>('/auth/me',token).then(setUser).catch(()=>{})}}/>;
 }
 const [raw,id]=route.split('/');const page=(NAV.some(n=>n.id===raw)||['asset-detail','case-detail'].includes(raw)?raw:'dashboard') as Page;
 const content=page==='dashboard'?<Dashboard token={token} nav={navigate}/>:
 page==='assets'?<Assets token={token} nav={navigate}/>:page==='geo'?<GeoPage token={token}/>:
 page==='asset-detail'?<AssetDetail token={token} id={id||fixtureAssets[0].id} nav={navigate}/>:
 page==='cases'?<Cases token={token} nav={navigate}/>:
 page==='case-detail'?<CaseDetail token={token} id={id||fixtureCases[0].id} nav={navigate}/>:
 page==='documents'?<Documents token={token} nav={navigate}/>:
 page==='reports'?<Reports token={token} nav={navigate}/>:page==='issuance'?<ReportIssuancePage token={token} userId={user.id}/>: 
 page==='billing'?<Billing token={token}/>:
 page==='audit'?<Audit token={token}/>:
 page==='notifications'?<NotificationsPage token={token}/>:page==='security'?<SecurityPage token={token} onSignedOut={forget}/>:
 page==='assignments'?<AssignmentsPage token={token}/>:
 page==='professional'?<ProfessionalTrustPage token={token}/>:page==='team'?<TeamPage token={token}/>:
 page==='tasks'?<TasksPage token={token}/>:
 page==='disputes'?<DisputesPage token={token}/>:
 page==='monitoring'?<MonitoringPage token={token}/>:
 page==='quotes'?<QuotesPage token={token}/>:
 page==='integrations'?<IntegrationsPage token={token}/>:page==='readiness'?<DeploymentReadinessPage token={token} role={user.role}/>:
 page==='access'?<AccessPage token={token}/>:page==='admin'?<AdminControlPage token={token} userId={user.id}/>:page==='members'?<MemberManagementPage token={token} userId={user.id}/>:page==='workflows'?<WorkflowAdminPage token={token} userId={user.id}/>:page==='content'?<ContentAdminPage token={token} userId={user.id}/>:page==='providers'?<NotificationProvidersPage token={token} userId={user.id}/>:
 <SettingsPage user={user}/>;
 return <Shell user={user} token={token} onLogout={logout} nav={navigate} page={page}>{content}</Shell>
}
